def get_bounding_box_and_interior(grid, r_start, c_start, target_color, H, W):
    """Get the bounding box and interior cells"""
    min_r, max_r = r_start, r_start
    min_c, max_c = c_start, c_start

    visited = set()
    queue = [(r_start, c_start)]
    visited.add((r_start, c_start))

    while queue:
        r, c = queue.pop()
        min_r = min(min_r, r)
        max_r = max(max_r, r)
        min_c = min(min_c, c)
        max_c = max(max_c, c)

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) not in visited and 0 <= nr < H and 0 <= nc < W:
                if grid[nr][nc] == target_color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    interior_cells = []
    for r in range(min_r+1, max_r):
        for c in range(min_c+1, max_c):
            interior_cells.append((r, c))

    return min_r, max_r, min_c, max_c, height, width, interior_cells

