import os,glob,re,json
from collections import deque

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

def apply_transformation(grid, H, W, background, rects):
    """Apply the transformation based on our hypothesized rules"""
    result = [row[:] for row in grid]

    for rect in rects:
        fill_color = None

        if len(rect['interior']) == 1:
            # Single cell center case: fill = bg + border + 1 (or similar)
            fill_color = rect['color'] + background + 1
        else:
            # Multi-cell interior: fill = |bg - border|
            fill_color = abs(background - rect['color'])

        # Fill the interior cells
        for r, c in rect['interior']:
            result[r][c] = fill_color

    return result

def find_rectangles(grid, H, W, background):
    """Find all rectangular frames in the grid"""
    rectangles = []

    # Find starting points for each color
    colors = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != background:
                color = grid[r][c]
                if color not in colors:
                    colors[color] = []
                colors[color].append((r, c))

    # Process each color group
    for color in sorted(colors.keys()):
        start = min(colors[color], key=lambda x: (x[0], x[1]))

        # Flood fill to find bounding box
        visited = set()
        queue = [(start[0], start[1])]
        visited.add((start[0], start[1]))

        while queue:
            r, c = queue.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) not in visited and 0 <= nr < H and 0 <= nc < W:
                    if grid[nr][nc] == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

        # Get bounding box
        rmin = min(r for r, c in visited)
        rmax = max(r for r, c in visited)
        cmin = min(c for r, c in visited)
        cmax = max(c for r, c in visited)

        # Interior cells (not on border)
        interior = []
        for r in range(rmin+1, rmax):
            for c in range(cmin+1, cmax):
                interior.append((r, c))

        rectangles.append({
            'color': color,
            'rmin': rmin, 'rmax': rmax,
            'cmin': cmin, 'cmax': cmax,
            'height': rmax - rmin + 1,
            'width': cmax - cmin + 1,
            'interior': interior,
            'interior_count': len(interior)
        })

    return rectangles

