    """Apply transformation based on hypothesized rules:
    - Single cell interior: fill = border + 1
    - Multi-cell interior: fill = |background - border|
    """
    result = [row[:] for row in grid]

    for rect in rects:
        if len(rect['interior']) == 1:
            # Single cell: fill = border + 1
            fill_color = rect['color'] + 1
        else:
            # Multi-cell: fill = |bg - border|
            fill_color = abs(background - rect['color'])

        for r, c in rect['interior']:
            result[r][c] = fill_color

    return result

