# Improved rectangle detection that checks for HOLLOW frames specifically
def find_hollow_frames(grid, H, W, background):
    """Find frames that are actually hollow (have different-colored pixels inside)"""
    frames = []
    colors = {}

    # Group connected cells of each color
    for r in range(H):
        for c in range(W):
            if grid[r][c] != background:
                color = grid[r][c]
                if color not in colors:
                    colors[color] = []
                colors[color].append((r, c))

    for color in sorted(colors.keys()):
        # Find bounding box
        cells = colors[color]
        rmins = [c[0] for c in cells]
        rmaxs = [c[0] for c in cells]
        cmins = [c[1] for c in cells]
        cmaxs = [c[1] for c in cells]

        rmin = min(rmins); rmax = max(rmaxs)
        cmin = min(cmins); cmax = max(cmaxs)

        # Get all cells on the border of the bounding box
        border_cells = []
        for r in range(rmin, rmax+1):
            for c in range(cmin, cmax+1):
                if r == rmin or r == rmax or c == cmin or c == cmax:
                    if grid[r][c] == color:
                        border_cells.append((r, c))

        # Check if all border cells are same color AND interior has mixed/different content
        interior_cells = []
        for r in range(rmin+1, rmax):
            for c in range(cmin+1, cmax):
                interior_cells.append((r, c))

        # Verify it's a proper frame: continuous border, not solid
        is_frame = len(border_cells) > 0 and len(cells) > len(border_cells)

        if is_frame:
            frames.append({
                'color': color,
                'border_cells': border_cells,
                'interior_cells': interior_cells,
                'height': rmax - rmin + 1,
                'width': cmax - cmin + 1,
                'is_solid': False
            })

    return frames

