def apply_my_rule(grid_in):
    """Apply the transformation rule:
    - Single-cell interior: fill = border_color + 1
    - Multi-cell interior: fill = |background - border_color|
    """
    H, W = len(grid_in), len(grid_in[0])
    bg = grid_in[0][0]

    # Find all frames using BFS/connected components
    found_rects = []
    visited = [[False]*W for _ in range(H)]

    def bfs(start_r, start_c, color):
        queue = [(start_r, start_c)]
        cells = [(start_r, start_c)]
        visited[start_r][start_c] = True

        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                    if grid_in[nr][nc] == color:
                        visited[nr][nc] = True
                        cells.append((nr, nc))
                        queue.append((nr, nc))

        return cells

    colors = set()
    for r in range(H):
        for c in range(W):
            if grid_in[r][c] != bg and (r,c) not in visited:
                color = grid_in[r][c]
                cells = bfs(r, c, color)
                if len(cells) > 1:
                    colors.add(color)

    for color in colors:
        all_cells = []
        for r in range(H):
            for c in range(W):
                if grid_in[r][c] == color and (r,c) not in visited:
                    all_cells.append((r,c))

        if all_cells:
            min_r, max_r = min(c[0] for c in all_cells), max(c[0] for c in all_cells)
            min_c, max_c = min(c[1] for c in all_cells), max(c[1] for c in all_cells)

            # Interior cells
            interior = []
            for r in range(min_r+1, max_r):
                for c in range(min_c+1, max_c):
                    interior.append((r,c))

            count = len(interior)
            fill = border_color + 1 if count == 1 else abs(bg - border_color)

            found_rects.append({
                'color': border_color,
                'interior': interior,
                'count': count,
                'fill': fill
            })

    return found_rects

