        max_r = max(b[0] for b in bboxes)
        min_c = min(b[1] for b in bboxes)
        max_c = max(b[1] for b in bboxes)

        # Check if it's a frame (has interior cells that are background)
        # Interior rows: min_r+1 to max_r-1, cols: min_c+1 to max_c-1
        has_interior = (max_r - min_r >= 2) and (max_c - min_c >= 2)

        if has_interior:
            # Count how many interior cells are NOT background (already filled)
            interior_count = 0
            for r_inner in range(min_r + 1, max_r):
                for c_inner in range(min_c + 1, max_c):
                    if grid[r_inner][c_inner] != background:
