    # Now fill interiors
    output = [row[:] for row in grid]

    for color, (min_r, max_r, min_c, max_c, count) in rectangles.items():
        if count == 1:
            # Single cell interior: fill with border+1
            fill_color = color + 1
        else:
            # Multi-cell interior: fill with |background - border|
            fill_color = abs(background - color)

